CREATE TABLE `commercial_plans` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`code` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`name` VARCHAR(120) NOT NULL,`description` VARCHAR(500) NULL,`quotas_json` JSON NOT NULL,`status` ENUM('draft','active','retired') NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`updated_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_commercial_plan_code`(`code`),KEY `idx_commercial_plan_status`(`status`,`updated_at`),CONSTRAINT `fk_commercial_plan_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_commercial_plan_updater` FOREIGN KEY(`updated_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `organization_plan_assignments` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`plan_id` CHAR(36) CHARACTER SET ascii NOT NULL,`period_start` DATETIME(3) NOT NULL,`period_end` DATETIME(3) NOT NULL,`status` ENUM('active','suspended','ended') NOT NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`updated_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_org_plan_assignment`(`organization_id`),KEY `idx_org_plan_period`(`status`,`period_end`),CONSTRAINT `fk_org_plan_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_plan_plan` FOREIGN KEY(`plan_id`) REFERENCES `commercial_plans`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_plan_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_org_plan_updater` FOREIGN KEY(`updated_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `commercial_quota_adjustments` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NOT NULL,`assignment_id` CHAR(36) CHARACTER SET ascii NOT NULL,`quota_key` VARCHAR(80) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,`delta_value` BIGINT NOT NULL,`reason` VARCHAR(500) NOT NULL,`status` ENUM('active','revoked') NOT NULL,`effective_at` DATETIME(3) NOT NULL,`expires_at` DATETIME(3) NULL,`revoked_by` CHAR(36) CHARACTER SET ascii NULL,`revoked_at` DATETIME(3) NULL,`version` INT UNSIGNED NOT NULL DEFAULT 1,`created_by` CHAR(36) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_quota_adjustment_org_key`(`organization_id`,`quota_key`,`status`,`expires_at`),CONSTRAINT `fk_quota_adjustment_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_quota_adjustment_assignment` FOREIGN KEY(`assignment_id`) REFERENCES `organization_plan_assignments`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_quota_adjustment_creator` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_quota_adjustment_revoker` FOREIGN KEY(`revoked_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `commercial_operations` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`route_key` VARCHAR(180) CHARACTER SET ascii NOT NULL,`idempotency_key` VARCHAR(255) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`result_json` JSON NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),UNIQUE KEY `uq_commercial_operation`(`actor_id`,`route_key`,`idempotency_key`),CONSTRAINT `fk_commercial_operation_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `commercial_views` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`observed_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_commercial_view_actor_time`(`actor_id`,`observed_at`),CONSTRAINT `fk_commercial_view_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_commercial_view_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `commercial_events` (`id` CHAR(36) CHARACTER SET ascii NOT NULL,`organization_id` CHAR(36) CHARACTER SET ascii NULL,`actor_id` CHAR(36) CHARACTER SET ascii NOT NULL,`event_type` VARCHAR(160) CHARACTER SET ascii NOT NULL,`resource_type` VARCHAR(100) CHARACTER SET ascii NOT NULL,`resource_id` CHAR(36) CHARACTER SET ascii NOT NULL,`payload_json` JSON NOT NULL,`request_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`trace_id` VARCHAR(128) CHARACTER SET ascii NOT NULL,`occurred_at` DATETIME(3) NOT NULL,PRIMARY KEY(`id`),KEY `idx_commercial_event_time`(`event_type`,`occurred_at`),KEY `idx_commercial_event_org_time`(`organization_id`,`occurred_at`),CONSTRAINT `fk_commercial_event_actor` FOREIGN KEY(`actor_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fk_commercial_event_org` FOREIGN KEY(`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
